#include <stdint.h>

const uint8_t mask = 0x01;

void setup() {
  uint8_t cppValue = 0x0F;
  cppValue ^= mask;  // portable C++ result: 0x0E

  uint8_t asmValue = 0x0F;
  // AVR-GCC-specific inline assembly; not portable to every Arduino board.
  asm volatile (
    "eor %0, %1"
    : "+r" (asmValue)  // output: read and written in a register
    : "r" (mask)       // input: mask is in a register
    : "cc"              // EOR changes condition flags
  );                  // asmValue is also 0x0E
  Serial.begin(9600);
  Serial.print(cppValue);
  Serial.print(' ');
  Serial.println(asmValue);  // demonstration output only; do not time Serial
}

void loop() {}
